from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class PrachTestResults(SchemaObject):
    time = SchemaField(name="time", not_null=True)
    no_pa_counter = SchemaField(name="noPaCounter", not_null=True)
    wrong_pa_counter = SchemaField(name="wrongPaCounter", not_null=True)
    wrong_timing_counter = SchemaField(name="wrongTimingCounter", not_null=True)
    detected_counter = SchemaField(name="detectedCounter", not_null=True)
    missed_counter = SchemaField(name="missedCounter", not_null=True)
    false_counter = SchemaField(name="falseCounter", not_null=True)
    idle_period_counter = SchemaField(name="idlePeriodCounter", not_null=True)

    def __init__(self, time=None, no_pa_counter=None, wrong_pa_counter=None, wrong_timing_counter=None,
                 detected_counter=None, missed_counter=None, false_counter=None, idle_period_counter=None):
        self.time = time
        self.no_pa_counter = no_pa_counter
        self.wrong_pa_counter = wrong_pa_counter
        self.wrong_timing_counter = wrong_timing_counter
        self.detected_counter = detected_counter
        self.missed_counter = missed_counter
        self.false_counter = false_counter
        self.idle_period_counter = idle_period_counter


class PrachTestParams(SchemaObject):
    beam_pattern_id = SchemaField(name="beamPatternIdArray", not_null=True)
    reporting_time_interval = SchemaField(name="reportingTimeInterval", not_null=True)
    ru_mode = SchemaField(name="ruMode", not_null=True)
    phys_cell_id = SchemaField(name="physCellId", not_null=True)
    nrarfcn = SchemaField(name="nrarfcn", not_null=True)
    expectation_slot = SchemaField(name="expectationSlot", not_null=True)
    receiving_slot = SchemaField(name="receivingSlot", not_null=True)
    prach_configuration_index = SchemaField(name="prachConfigurationIndex", not_null=True)
    accepted_timing_error = SchemaField(name="acceptedTimingError", not_null=True)
    constant_offset = SchemaField(name="constantOffset", not_null=True)
    delay_pattern_single_step_duration = SchemaField(name="delayPatternSingleStepDuration", not_null=True)
    pfa_target_prach_id = SchemaField(name="pfaTargetPrachId", not_null=True)
    prach_root_sequence_index = SchemaField(name="prachRootSequenceIndex", not_null=True)
    preamble_index = SchemaField(name="preambleIndex", not_null=True)
    zero_correlation_zone_config = SchemaField(name="zeroCorrelationZoneConfig", not_null=True)
    prach_sequence_type = SchemaField(name="prachSequenceType", not_null=True)
    act_prach_format_c2_with_scs = SchemaField(name="actPrachFormatC2WithScs", optional=True)


    def __init__(self, beam_pattern_id=None, reporting_time_interval=None, ru_mode=None, phys_cell_id=None,
                 nrarfcn=None, expectation_slot=None, receiving_slot=None, prach_configuration_index=None,
                 accepted_timing_error=None, constant_offset=None, delay_pattern_single_step_duration=None,
                 pfa_target_prach_id=None, prach_root_sequence_index=None, preamble_index=None,
                 zero_correlation_zone_config=None, prach_sequence_type=None, act_prach_format_c2_with_scs=None):
        self.beam_pattern_id = beam_pattern_id
        self.reporting_time_interval = reporting_time_interval
        self.ru_mode = ru_mode
        self.phys_cell_id = phys_cell_id
        self.nrarfcn = nrarfcn
        self.expectation_slot = expectation_slot
        self.receiving_slot = receiving_slot
        self.prach_configuration_index = prach_configuration_index
        self.accepted_timing_error = accepted_timing_error
        self.constant_offset = constant_offset
        self.delay_pattern_single_step_duration = delay_pattern_single_step_duration
        self.pfa_target_prach_id = pfa_target_prach_id
        self.prach_root_sequence_index = prach_root_sequence_index
        self.preamble_index = preamble_index
        self.zero_correlation_zone_config = zero_correlation_zone_config
        self.prach_sequence_type = prach_sequence_type
        self.act_prach_format_c2_with_scs = act_prach_format_c2_with_scs


class GetPrachCPCONFIGV1(SchemaObject):
    prach_test_params = SchemaField(name="prachTestParams", klass=PrachTestParams)
    prach_test_results = SchemaField(name="prachTestResults", klass=PrachTestResults, many=True)

    def __init__(self, prach_test_params=None, prach_test_results=None):
        self.prach_test_params = prach_test_params
        self.prach_test_results = prach_test_results

        super(GetPrachCPCONFIGV1, self).__init__()
